INSERT INTO products_product VALUES (11, 'The Grad Gleam Bouquet', 'Pompon mum, Rose, Eustoma, Oxypetalum Tweedia, Astilbe', 'A Bouquet of Flowers', 'Spring', 'Toast to triumphs with a bouquet that blends playful grins and graduation pride! Perfect for honoring their big day, this cheerful companion, complete with a cap-toting smile, brings warmth to every photo, party, and exciting new chapter ahead.\r\n\r\nFloral Arrangement includes: Pompon mum, Rose, Eustoma, Oxypetalum Tweedia, Astilbe\r\n\r\nSize:\r\n20cm (W) X 30cm (H)', 'products/2025/10/19/Pasted_image_8.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 57, 1, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 1, 'a');
INSERT INTO products_product VALUES (10, 'Only You', 'Garden Roses in Red & Cream, Rancuculus, Astilbe in Bloom Bucket.', 'Grand Glass Flowers', 'Spring', 'A stunning display of Garden Roses in deep red and soft cream hues, paired with plush Ranunculus and feathery Astilbe. Only You exudes classic elegance and romantic charm, perfect for sophisticated gifting or as a captivating centerpiece.\r\n\r\nFloral Arrangement includes: Garden Roses in Red & Cream, Rancuculus, Astilbe in Bloom Bucket.\r\n\r\nSize in approximate diameter: (Medium) 40cm W, (Large) 60cm W\r\n\r\nThe Bloom Bucket collection comes presented in a premium bucket with hand-drawn floral illustrations; it serves as a vase so the blooms remains as impeccable as the day it was crafted. The medium-sized bucket also comes with a satin carrying strap that can be slung on one shoulder - a chic way to carry and display your gift.', 'products/2025/10/19/Pasted_image_9.0.png', 'products/2025/10/19/Pasted_image_9.1.png', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 54, 25, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 4, 'a');
INSERT INTO products_product VALUES (9, 'Lasting Love', 'White Rose, Ranunculus, Viburnum, Eustoma, Hypericum, Lilac & Assorted Greenery.', 'A Bouquet of Flowers', 'Spring', 'Lasting Love is a symphony of elegance with pristine White Roses and tender Ranunculus. The freshness of Viburnum, the poise of Eustoma, and the charm of Hypericum are accented by fragrant Lilac, all nestled within a verdant array of assorted greenery for a breath of serene sophistication.\r\n\r\nFloral Arrangement includes: White Rose, Ranunculus, Viburnum, Eustoma, Hypericum, Lilac & Assorted Greenery.\r\n\r\nSize in approximate diameter: (Small) 30cm, (Medium) 40cm, (Large) 50cm', 'products/2025/10/19/Pasted_image_9.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 49, 57, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 1, 'a');
INSERT INTO products_product VALUES (8, 'Blooms Baby Hamper Gift Set (Violet)', 'Global Selection of Blooms', 'Flower and  Baby Gift Set', 'Spring', 'The perfect baby hamper for the little ones! A beautiful bouquet arrangement of seasonal blooms and a set of 6 pieces gift set from PAVO BABY; BPA FREE and FDA certified; the set includes a teether, pacifier clipper, cotton bib, water cup set, bowl and plate set with cutleries.', 'products/2025/10/19/Pasted_image_15.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 45, 43, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 2, 'a');
INSERT INTO products_product VALUES (7, 'Exquisite Peace', 'Anthurium, Delphinium, Hydrangea, and Roses', 'Flowers with Stand', 'Spring', 'Timeless arrangement with stand.\r\n \r\nCelebrate a life beautifully lived with Exquisite Peace, a serene floral arrangement that honors cherished memories with quiet elegance. This graceful standing display combines the symbolic beauty of anthurium (representing lasting care), delphinium (symbolizing spiritual connection), and hydrangea (embracing heartfelt emotions), complemented by roses, stock, and eustoma in soothing tones. Set against lush foliage, it creates a natural sanctuary of remembrance and peace.\r\n\r\nDimension: 95cm(W) x 215cm(H)', 'products/2025/10/19/Pasted_image_14.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 41, 39, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 3, 'a');
INSERT INTO products_product VALUES (6, 'Louvre', 'snapdragons, amaryllis, eustomas, and roses', 'Flowers with Stand', 'Spring', 'Elegant and sophisticated arrangement with stand.\r\n \r\nLush and exotic foliage embrace gracious snapdragons, splendid amaryllis, eye-catching eustomas, and timeless roses to create a striking display.\r\n \r\n Dimension :\r\n \r\n 80cm(W) x 85cm(H) *flower size only\r\n \r\n 80cm(W) x 190cm(H) *including the stand', 'products/2025/10/19/Pasted_image_10.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 36, 57, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 1, 'a');
INSERT INTO products_product VALUES (5, 'Amour Amour', 'Pink Anthurium, Tulip, Rancuculus, Eustoma & Didiscus in Glass Container.', 'Deluxe Crystal Glass flower Set', 'Spring', "A chic arrangement Amour Amour cradles a selection of Pink Anthuriums, soft-hued Tulips, and plush Ranunculus, accented by the graceful Eustoma and lace-like Didiscus. This arrangement exudes a modern yet soft charm, creating a statement piece that's both sophisticated and inviting.\r\n\r\nFloral Arrangement includes: Pink Anthurium, Tulip, Rancuculus, Eustoma & Didiscus in Glass Container.\r\n\r\nDimension: (Small)25cm H x 30cm W, (Medium) - 30cm H x 30cm W\r\n\r\n \r\n\r\n*Vase style may vary slightly, subject to stock availability", 'products/2025/10/19/Pasted_image_11.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 34, 45, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 2, 'a');
INSERT INTO products_product VALUES (4, 'Carrousel', 'Global Selection of Blooms, Sunflowers', 'Flowers with Stand', 'Spring', 'Timeless arrangement with stand.\r\n \r\nStep into a world of vibrant motion with Carrousel, a show-stopping floral stand that captivates with its playful energy and bold contrasts. This dynamic arrangement marries exotic foliage with a global selection of blooms, featuring the unexpected charm of pistachio-hued hydrangeas and the joyful radiance of sunflowers. Like its namesake, this design delights with a sense of movement and celebration.\r\n\r\nDimension : \r\n75cm(W) x 80cm(H) *flower size only\r\n75cm(W) x 190cm(H) *including the stand', 'products/2025/10/19/Pasted_image_12.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 31, 58, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 4, 'a');
INSERT INTO products_product VALUES (3, 'Marjorelle', 'Orchids with extravagant foliage', 'Deluxe Crystal Glass flower Set', 'Spring', "Marjorelle , the vase arrangement showcases the sophisticated allure of Orchids, standing tall among an array of extravagant foliage. The lush greenery provides a sumptuous backdrop, highlighting the Orchids' exotic charm and transforming any space into a luxurious tropical haven.\r\n\r\nFloral Arrangement includes: Orchids with extravagant foliage\r\n\r\nSize in approximate diameter: Size : 110cm(H) x 70cm(W)\r\n\r\n \r\n\r\n*Vase style may vary slightly, subject to stock availability", 'products/2025/10/19/Pasted_image_13.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 28, 51, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 3, 'a');
INSERT INTO products_product VALUES (2, 'Misthaven Rabbit', 'Pink Rose, Spray rose, Stock, Scabiosa, Astilbe and Greenery', 'Boxes Flower and Gift', 'Spring', 'Misthaven Rabbit reminds you of dawn’s first blush kissed by dew, where silken petals drift like whispered secrets. A wild garden’s tender soul, woven with textures soft as twilight mist.\r\n\r\nAmidst this idyllic reverie, a gentle companion watches - a symbol of quiet wonder and timeless grace.\r\n\r\nFloral Arrangement includes: Pink Rose, Spray rose, Stock, Scabiosa, Astilbe and Greenery\r\n\r\n\r\nSize:\r\n40cm (W) X 50cm (H)', 'products/2025/10/19/Pasted_image_14.0.png', 'products/2025/10/19/Pasted_image_14.1.png', 'products/2025/10/19/Pasted_image_14.2.png', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 24, 4, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 5, 'a');
INSERT INTO products_product VALUES (12, 'Caps Off to Joy Bouquet', "Graduation Bunny (bunny's outfit might be different), Helianthus, Gerbera, Baby Rose, Eustoma, Oxypetalum Tweedia, Panicum fountain", 'A Bouquet of Flowers', 'Spring', "Hop into celebration with a bouquet that’s equal parts playful bunny charm and sunny graduation glow! Perfect for lighting up their big day, this cheerful mix of warmth and whimsy makes every photo, party, and new adventure feel extra special.\r\n\r\nHere’s to their shining moment!\r\n\r\nFloral Arrangement includes: Graduation Bunny (bunny's outfit might be different), Helianthus, Gerbera, Baby Rose, Eustoma, Oxypetalum Tweedia, Panicum fountain\r\n\r\nSize:\r\n35cm (W) X 45cm (H)", 'products/2025/10/19/Pasted_image_5.png', '', '', '', '', '', '', True, datetime.datetime(2025, 10, 19, 12, 57, 55, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 2, 'a');
INSERT INTO products_product VALUES (16, 'Dolce Parfait', 'Vanda, Antique Rose, Eustoma, Scabiosa, Didiscus, Panicum Fountain Greenery', 'Grand Glass Flowers', 'Spring', 'Wrap your home in autumn’s warmth with Dolce Parfait—a rustic bucket filled with velvety antique roses, exotic vanda orchids, and a whisper of scabiosa and eustoma. Textured didiscus and cascading panicum greenery add soft movement, creating a cozy, nostalgic arrangement that feels like a hug in floral form. Perfect for bringing seasonal comfort to any room. \r\n\r\nFloral Arrangement includes: Vanda, Antique Rose, Eustoma, Scabiosa, Didiscus, Panicum Fountain Greenery\r\n\r\nSize:\r\n40cm W (Medium), 60cm W (Large)\r\n\r\nWhile we try our best to include the exact ingredients for the bouquet, seasonal adaptation may be necessary in creation of the same palette.', 'products/2025/10/19/Pasted_image_6.png', 'products/2025/10/19/Pasted_image_6.1.png', 'products/2025/10/19/Pasted_image_6.2.png', '', '', '', '', True, datetime.datetime(2025, 10, 19, 13, 9, 31, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 5, 'a');
INSERT INTO products_product VALUES (15, 'Gilded Autumn Whispers', 'Cynbidium, Rose & Assorted Greenery', 'A Bouquet of Flowers', 'Spring', 'Let these soft hues and delicate textures turn your cozy nook into an autumnal retreat, where every glance feels like a gentle, gilded secret shared with the season.\r\n\r\nIt’s not just a decor piece; it’s a daily reminder that autumn’s magic lies in these small, elegant touches that make your space feel like a sanctuary tailored to slow, beautiful living.\r\n\r\nFloral Arrangement includes: Cynbidium, Rose & Assorted Greenery. \r\n\r\nSize: \r\n35cm W (Small)\r\n45cm W (Large)', 'products/2025/10/19/Pasted_image_4.png', 'products/2025/10/19/Pasted_image_4.1.png', 'products/2025/10/19/Pasted_image_4.2.png', 'products/2025/10/19/Pasted_image_4.3.png', '', '', '', True, datetime.datetime(2025, 10, 19, 13, 7, 7, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 4, 'a');
INSERT INTO products_product VALUES (14, 'Velvet Autumn Reverie', 'Purple Rose, Phlox, Wheat & Autumn Greenery Bouquet in Vase', 'Grand Glass Flowers', 'Spring', "Capture the deep, luxurious comfort of the season. This arrangement is more than a bouquet in the vase; it's an invitation to slow down, to savor the rich, quiet moments.\r\n\r\nImagine it gracing your home, its warmth transforming your space into a serene autumn sanctuary. It’s the essence of cozy elegance, a velvet dream for the home.\r\n\r\nFloral Arrangement includes: Purple Rose, Phlox, Wheat & Autumn Greenery Bouquet in Vase\r\n\r\nSize: \r\n30cm W (Small)\r\n35cm W (Medium)\r\n40cm W (Large)", 'products/2025/10/19/Pasted_image.png', 'products/2025/10/19/Pasted_image_2.png', 'products/2025/10/19/Pasted_image_3.png', '', '', '', '', True, datetime.datetime(2025, 10, 19, 13, 4, 17, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 3, 'a');
INSERT INTO products_product VALUES (13, 'Autumn’s Opulent Embrace', 'Hydrangea, Garden Rose, Spray Rose, Vanda & Greenery', 'Grand Glass Flowers', 'Spring', 'As autumn unfolds with its rich tapestry of hues and cozy warmth, let this arrangement be the heart of your living moments.\r\n\r\nWhether it’s gracing your breakfast nook as you sip morning coffee, adding a touch of luxe charm to your evening dinner party, or simply resting on your desk to transform a workday into something sublime - this piece wraps your days in the opulence of fall.\r\n\r\nIt’s not just decor; it’s a daily invitation to pause, breathe in the season’s beauty, and let the richness of autumn infuse every corner of your lifestyle with comfort and refined style.\r\n\r\nFloral Arrangement includes: Hydrangea, Garden Rose, Spray Rose, Vanda & Greenery.\r\n\r\nSize: \r\n40cm W (Small), 60cm W (Large)', 'products/2025/10/19/Pasted_image_5.0.png', 'products/2025/10/19/Pasted_image_5.1.png', 'products/2025/10/19/Pasted_image_5.2.png', '', '', '', '', True, datetime.datetime(2025, 10, 19, 13, 0, 2, tzinfo=datetime.timezone(datetime.timedelta(seconds=28800))), 3, 'a');
